code.Java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextDouble()) {
            double val = sc.nextDouble();
            int k = sc.nextInt();
            System.out.printf("%." + k + "f\n", val);
        }
    }
}

